export type RSSData = {
  url: string
  title: string
  image?: string
  path?: string
  isDocs?: boolean
}

export default defineBackground(() => {
  import("~/background/index")
})

import type { RSSData } from "~/lib/types"

import RSSItem from "./RSSItem"

function RSSList({ type, list }: { type: string; list: RSSData[] }) {
  if (list.length === 0) {
    return null
  }
  return (
    <div className="space-y-4">
      <h2 className="text-base font-bold">{chrome.i18n.getMessage(type)}</h2>
      <ul className="overflow-x-auto w-max min-w-full max-w-[700px]">
        {list.map((item) => (
          <RSSItem key={item.url + item.title} item={item} type={type} />
        ))}
      </ul>
    </div>
  )
}

export default RSSList

import { getConfig } from "~/lib/config"

chrome.action?.setBadgeBackgroundColor?.({
  color: "#F62800",
})

chrome.action?.setBadgeTextColor?.({
  color: "#fff",
})

export const setBadge = async (text: string, tabId: number) => {
  const config = await getConfig()

  if (config.notice.badge) {
    chrome.action.setBadgeText({
      text,
      tabId,
    })
  }
}

import { sendToBackground } from "~/lib/messaging"
import { getPageRSS } from "~/lib/rss"

sendToBackground({
  name: "contentReady",
})

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.name === "requestHTML") {
    sendResponse(document.documentElement.outerHTML)
  } else if (msg.name === "requestPageRSS") {
    getPageRSS().then((data) => {
      sendResponse(data)
    })
    return true
  }
})

export {}

// https://developer.chrome.com/docs/extensions/reference/api/offscreen
let creating

async function setupOffscreenDocument(path: string) {
  const offscreenUrl = chrome.runtime.getURL(path)

  const existingContexts = (await (chrome.runtime as any).getContexts({
    contextTypes: ["OFFSCREEN_DOCUMENT"] as any,
    documentUrls: [offscreenUrl],
  })) as chrome.runtime.ExtensionContext[] | undefined

  if (existingContexts?.length) {
    return
  }

  if (creating) {
    await creating
  } else {
    creating = chrome.offscreen.createDocument({
      url: offscreenUrl,
      reasons: [chrome.offscreen.Reason.IFRAME_SCRIPTING],
      justification: "Get RSS in the sandbox for enhanced security.",
    })
    await creating
    creating = null
  }
}

export { setupOffscreenDocument }

